<div class="page-header order-detail-heading"><div><a class="back-link" href="/pedidos">← Volver a pedidos</a><span class="eyebrow">Detalle operativo</span><h1><?= $escape($order['codigo_pedido']) ?></h1><p>Seguimiento <?= $escape($order['codigo_seguimiento']) ?></p></div><div class="heading-badges"><span class="status-badge status-large status-<?= $escape(strtolower(str_replace(' ', '-', $order['estado']))) ?>"><?= $escape($order['estado']) ?></span><?php if ($urgency['key'] !== 'none'): ?><span class="urgency-badge urgency-large urgency-<?= $escape($urgency['key']) ?>"><?= $escape($urgency['label']) ?></span><?php endif; ?></div></div>
