    <div>
        <article class="card"><div class="card-heading"><div><span class="eyebrow">Información</span><h2>Datos del pedido</h2></div></div><dl class="data-list"><div><dt>Cliente</dt><dd><?= $escape($order['cliente']) ?></dd></div><div><dt>Teléfono</dt><dd><?= $escape($order['telefono']) ?></dd></div><div><dt>Correo</dt><dd><?= $escape($order['correo'] ?: '—') ?></dd></div><div><dt>Sede</dt><dd><?= $escape($order['sede']) ?></dd></div><div><dt>Modalidad</dt><dd><?= $escape(ucfirst(strtolower($order['modalidad']))) ?></dd></div><div class="required-date"><dt>Fecha requerida</dt><dd><?= date('d/m/Y', strtotime($order['fecha_requerida'])) ?></dd></div><div class="full-data"><dt>Dirección</dt><dd><?= $escape($order['direccion_entrega'] ?: 'Recojo en ' . $order['sede']) ?></dd></div><div><dt>Registrado por</dt><dd><?= $escape($order['registrado_por']) ?></dd></div></dl><?php if ($order['observaciones']): ?><div class="note"><strong>Observaciones</strong><p><?= nl2br($escape($order['observaciones'])) ?></p></div><?php endif; ?></article>
