    </div>
    <aside>
        <article class="card action-card"><span class="eyebrow">Próxima acción</span><?php if ($transitions): ?><h2><?= $escape($order['next_action']) ?></h2><p>Avanza el pedido cuando se complete el paso actual.</p><form method="POST" action="/pedidos/<?= (int) $order['id_pedido'] ?>/estado"><?= Csrf::field() ?><div class="form-group"><label for="estado">Nuevo estado</label><select id="estado" name="estado" required><?php foreach ($transitions as $state): ?><option value="<?= $escape($state) ?>"><?= $escape($state) ?></option><?php endforeach; ?></select></div><div class="form-group section-gap-sm"><label for="observacion">Nota del cambio</label><textarea id="observacion" name="observacion" maxlength="250" placeholder="Contexto opcional para la trazabilidad"></textarea></div><button class="btn btn-primary btn-block section-gap-sm" type="submit">Actualizar estado</button></form><?php else: ?><h2>Flujo completado</h2><p class="empty-state">Este pedido se encuentra en un estado final.</p><?php endif; ?></article>
